import{_ as r,c as t,o as a,a5 as o}from"./chunks/framework.DuCYAsAJ.js";const s=JSON.parse('{"title":"可观测性：指标、追踪与日志","description":"","frontmatter":{"title":"可观测性：指标、追踪与日志","source":"https://app.devin.ai/org/feed/wiki/qiqi776/zfeed?branch=main#9.2","branch":"main","level":1,"order":9.2,"date":"2026-05-24T00:00:00.000Z"},"headers":[],"relativePath":"posts/projects/zfeed/09-infrastructure-and-deployment/02-observability-metrics-tracing-and-logging.md","filePath":"posts/projects/zfeed/09-infrastructure-and-deployment/02-observability-metrics-tracing-and-logging.md","lastUpdated":1779632679000}'),c={name:"posts/projects/zfeed/09-infrastructure-and-deployment/02-observability-metrics-tracing-and-logging.md"};function l(i,e,d,b,h,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="可观测性-指标、追踪与日志" tabindex="-1">可观测性：指标、追踪与日志 <a class="header-anchor" href="#可观测性-指标、追踪与日志" aria-label="Permalink to &quot;可观测性：指标、追踪与日志&quot;">​</a></h1><details><summary>相关源文件</summary><ul><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1" target="_blank" rel="noreferrer">README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/config/config_env_test.go" target="_blank" rel="noreferrer">app/rpc/search/internal/config/config_env_test.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/content-rpc.Dockerfile" target="_blank" rel="noreferrer">build/content-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/count-rpc.Dockerfile" target="_blank" rel="noreferrer">build/count-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/front-api.Dockerfile" target="_blank" rel="noreferrer">build/front-api.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/interaction-rpc.Dockerfile" target="_blank" rel="noreferrer">build/interaction-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/build/user-rpc.Dockerfile" target="_blank" rel="noreferrer">build/user-rpc.Dockerfile</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env" target="_blank" rel="noreferrer">deploy/.env</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/README.md?plain=1" target="_blank" rel="noreferrer">deploy/README.md</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml" target="_blank" rel="noreferrer">deploy/docker-compose.yml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf" target="_blank" rel="noreferrer">deploy/nginx/default.conf</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml</a></li><li><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/rules/zfeed-benchmark-alerts.yml" target="_blank" rel="noreferrer">deploy/prometheus/rules/zfeed-benchmark-alerts.yml</a></li></ul></details><p>本页描述 <code>zfeed</code> 系统的可观测性栈。该架构使用 <code>go-zero</code> 框架的原生可观测能力，并通过业务自定义指标和集中式日志流水线进行增强。</p><h2 id="可观测性栈总览" tabindex="-1">可观测性栈总览 <a class="header-anchor" href="#可观测性栈总览" aria-label="Permalink to &quot;可观测性栈总览&quot;">​</a></h2><p>系统采用多层可见性方案：</p><ol><li>指标：每个服务都有 Prometheus exporter，用于基础设施（CPU/Mem）、gRPC/HTTP 延迟和自定义业务计数器。</li><li>追踪：通过 OpenTelemetry（OTEL）和 Jaeger 实现分布式追踪，并跨 HTTP 与 gRPC 边界传播 <code>traceparent</code> header。</li><li>日志：结构化 JSON 日志，并为访问、错误、慢查询和统计信息使用专用文件。</li><li>日志流水线：通过 Filebeat → Logstash 流水线进行日志收集和处理。</li></ol><h3 id="可观测性数据流" tabindex="-1">可观测性数据流 <a class="header-anchor" href="#可观测性数据流" aria-label="Permalink to &quot;可观测性数据流&quot;">​</a></h3><p>下图展示可观测性数据如何从微服务流向监控基础设施。</p><p>数据流：从服务到可观测性后端</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L1-L300" target="_blank" rel="noreferrer">deploy/docker-compose.yml#1-300</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml#L1-L38" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml#1-38</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L57-L62" target="_blank" rel="noreferrer">README.md#57-62</a></p><hr><h2 id="指标与监控" tabindex="-1">指标与监控 <a class="header-anchor" href="#指标与监控" aria-label="Permalink to &quot;指标与监控&quot;">​</a></h2><p>每个服务都会在专用端口暴露 Prometheus 指标端点。这通过服务 <code>.yaml</code> 配置中的 <code>Prometheus</code> 小节完成 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L11-L14" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#11-14</a></p><h3 id="服务-exporter-端口" tabindex="-1">服务 Exporter 端口 <a class="header-anchor" href="#服务-exporter-端口" aria-label="Permalink to &quot;服务 Exporter 端口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>Exporter 端口</th><th>环境变量</th></tr></thead><tbody><tr><td><code>front-api</code></td><td><code>9290</code></td><td><code>PROM_PORT</code></td></tr><tr><td><code>content-rpc</code></td><td><code>9291</code></td><td><code>CONTENT_PROM_PORT</code></td></tr><tr><td><code>count-rpc</code></td><td><code>9292</code></td><td><code>COUNT_PROM_PORT</code></td></tr><tr><td><code>interaction-rpc</code></td><td><code>9293</code></td><td><code>INTERACTION_PROM_PORT</code></td></tr><tr><td><code>user-rpc</code></td><td><code>9294</code></td><td><code>USER_PROM_PORT</code></td></tr><tr><td><code>search-rpc</code></td><td><code>9295</code></td><td><code>SEARCH_PROM_PORT</code></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L35-L41" target="_blank" rel="noreferrer">deploy/.env#35-41</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/prometheus/prometheus.yml#L8-L38" target="_blank" rel="noreferrer">deploy/prometheus/prometheus.yml#8-38</a></p><h3 id="自定义业务指标" tabindex="-1">自定义业务指标 <a class="header-anchor" href="#自定义业务指标" aria-label="Permalink to &quot;自定义业务指标&quot;">​</a></h3><p><code>go-zero</code> 会自动提供 RPC/HTTP 延迟指标，系统也为特定业务事件实现了自定义指标。典型例子是 <code>search-rpc</code> 服务，它会追踪搜索性能和缓存效果。</p><p>在 <code>app/rpc/search/internal/logic/observability.go</code> 中定义了以下指标：</p><ul><li><code>metricSearchRequestDuration</code>：Histogram，用带有 <code>entity</code>、<code>backend</code> 和 <code>cache_status</code> 的标签追踪搜索延迟 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L30-L37" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#30-37</a></li><li><code>metricSearchCacheTotal</code>：Counter，用于追踪不同层级中的搜索缓存命中/未命中情况 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L64-L71" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#64-71</a></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L29-L71" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#29-71</a></p><hr><h2 id="分布式追踪" tabindex="-1">分布式追踪 <a class="header-anchor" href="#分布式追踪" aria-label="Permalink to &quot;分布式追踪&quot;">​</a></h2><p>分布式追踪使用 OpenTelemetry 实现。它让开发者可以追踪单个请求从 Nginx 网关进入 <code>front-api</code>，再进入多个下游 RPC 服务的完整路径。</p><h3 id="实现细节" tabindex="-1">实现细节 <a class="header-anchor" href="#实现细节" aria-label="Permalink to &quot;实现细节&quot;">​</a></h3><ul><li>Header 传播：Nginx 映射 <code>X-Request-Id</code>，并将 <code>traceparent</code> header 传递给上游 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L1-L21" target="_blank" rel="noreferrer">deploy/nginx/default.conf#1-21</a></li><li>OTEL 配置：服务配置为通过 gRPC（4317 端口）把 trace 发送到 <code>otel-collector</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L4-L9" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#4-9</a></li><li>采样：开发环境默认配置为 <code>Sampler: 1.0</code>，也就是 100% 采样 <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L9-L9" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#9</a></li></ul><p>追踪基础设施映射</p><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/nginx/default.conf#L65-L68" target="_blank" rel="noreferrer">deploy/nginx/default.conf#65-68</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L4-L9" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#4-9</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L51-L59" target="_blank" rel="noreferrer">deploy/.env#51-59</a></p><hr><h2 id="日志架构" tabindex="-1">日志架构 <a class="header-anchor" href="#日志架构" aria-label="Permalink to &quot;日志架构&quot;">​</a></h2><p>系统使用结构化 JSON 日志。<code>go-zero</code> 的日志库（<code>logx</code>）配置为根据日志类型输出到特定文件。</p><h3 id="日志类别" tabindex="-1">日志类别 <a class="header-anchor" href="#日志类别" aria-label="Permalink to &quot;日志类别&quot;">​</a></h3><p>日志存放在 <code>${LOG_PATH}/{service-name}/</code> 下，并按类别拆分：</p><ul><li><code>access.log</code>：记录每个 HTTP/gRPC 请求，包括状态码和耗时。</li><li><code>error.log</code>：记录 <code>error</code> 和 <code>fatal</code> 级别日志，并带有堆栈跟踪。</li><li><code>slow.log</code>：记录超过定义阈值的请求或数据库查询，例如 <code>defaultSearchSlowThreshold = 200ms</code> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L26-L26" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#26</a></li><li><code>stat.log</code>：周期性记录服务资源使用情况统计。</li></ul><h3 id="日志配置" tabindex="-1">日志配置 <a class="header-anchor" href="#日志配置" aria-label="Permalink to &quot;日志配置&quot;">​</a></h3><p>配置文件（如 <code>search.yaml</code>）中的 <code>Log</code> 小节定义轮转策略和格式：</p><ul><li><code>Mode: &quot;file&quot;</code></li><li><code>Encoding: &quot;json&quot;</code></li><li><code>Rotation: &quot;daily&quot;</code></li></ul><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/etc/search.yaml#L16-L32" target="_blank" rel="noreferrer">app/rpc/search/etc/search.yaml#16-32</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/README.md?plain=1#L59-L59" target="_blank" rel="noreferrer">README.md#59</a></p><h3 id="日志收集流水线" tabindex="-1">日志收集流水线 <a class="header-anchor" href="#日志收集流水线" aria-label="Permalink to &quot;日志收集流水线&quot;">​</a></h3><p>启用 <code>ENABLE_LOG_PIPELINE</code> 后，系统使用轻量 ELK 栈：</p><ol><li>Filebeat：挂载宿主机日志目录，并监听 <code>/var/log/zfeed</code> 中的新日志条目。</li><li>Logstash：接收 Filebeat 发送的日志，解析 JSON 结构，并可将日志路由到存储（Elasticsearch）或后续处理环节。</li></ol><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/.env#L49-L50" target="_blank" rel="noreferrer">deploy/.env#49-50</a> <a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/deploy/docker-compose.yml#L19-L19" target="_blank" rel="noreferrer">deploy/docker-compose.yml#19</a></p><hr><h2 id="实现参考-search-观测" tabindex="-1">实现参考：Search 观测 <a class="header-anchor" href="#实现参考-search-观测" aria-label="Permalink to &quot;实现参考：Search 观测&quot;">​</a></h2><p><code>search-rpc</code> 服务中的 <code>observeSearch</code> 函数展示了如何为复杂业务操作集成指标和日志。</p><table tabindex="0"><thead><tr><th>代码实体</th><th>职责</th><th>文件引用</th></tr></thead><tbody><tr><td><code>searchObservation</code></td><td>保存单次搜索操作的元数据，例如延迟、结果数和使用的后端。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L73-L91" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#73-91</a></td></tr><tr><td><code>observeSearch</code></td><td>记录指标并写入结构化日志的主函数，包括对慢请求调用 <code>.Sloww</code>。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L93-L159" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#93-159</a></td></tr><tr><td><code>metricSearchRequestDuration</code></td><td>面向搜索延迟的 Prometheus Histogram。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L30-L37" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#30-37</a></td></tr><tr><td><code>logx.Field</code></td><td>用于给日志添加结构化字段的辅助函数，便于在 Logstash 中过滤。</td><td><a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L128-L151" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#128-151</a></td></tr></tbody></table><p>来源：<a href="https://github.com/qiqi776/zfeed/blob/bcc7e04e/app/rpc/search/internal/logic/observability.go#L1-L188" target="_blank" rel="noreferrer">app/rpc/search/internal/logic/observability.go#1-188</a></p>',47)])])}const f=r(c,[["render",l]]);export{s as __pageData,f as default};
